   271	        }
   272	
   273	        seg_idx = omf_get_idx (buf + ct, buf_size - ct);
   274	
   275	        if (buf[ct] & 0x80) { // sizeof base segment index
   276	                ct += 2;
   277	        } else {
   278	                ct++;
   279	        }
   280	
   281	        if (!base_grp && !seg_idx) {
   282	                ct += 2;
   283	        }
